        c = c.strip().rstrip('.').strip().strip("'\"")
        if not c: return None
        words = c.split()
        # Find leftmost start position such that all subsequent words are TitleCase or allowed connectors
        n = len(words)
        connectors = {'&', '/', 'and', 'of', 'the', 'a', 'an', 'on', 'or', 'for', 'in', '-'}
        # Try each possible start, prefer earlier (longer tail)
        best = None
