                    continue
                if ww in connectors:
                    continue
                if re.match(r"^[\(\)/&\-\']", ww):
                    continue
                ok = False
                break
            # Also first word must start uppercase
            if ok and words[i][0].isupper():
                cand = ' '.join(words[i:])
                if cand and len(cand) <= 60 and not re.search(r'\d', cand):
                    best = cand
                    break
        return best

    cleaned = [title_tail(c) for c in chunks]

