import re

def extract_categories_v5(desc):
    # Strip location prefix - handle several patterns
    # Find first "<ST>," that follows a city pattern
    # Pattern: "<city>, <ST>," or "in <City>, <ST>"
    # We'll just find first occurrence of ", XX," where XX is a state code
    m = re.search(r'(?:in |at |Situated at |This |Situated in |Located in |Located at )([^,]+),\s*([A-Z]{2})[,\s]', desc)
    rest = desc
    if m and m.group(2) in US_STATES:
        rest = desc[m.end()-1:]  # cut the prefix part
    else:
        m2 = re.search(r',\s*([A-Z]{2}),', desc)
        if m2 and m2.group(1) in US_STATES:
            rest = desc[m2.end():]

    chunks = re.split(r'\s*,\s*', rest)

    def title_tail(c):
        c = c.strip().rstrip('.').strip().strip("'\"")
        if not c: return None
        words = c.split()
        if not words: return None
        connectors = {'&', '/', 'and', 'of', 'the', 'a', 'an', 'on', 'or', 'for', 'in', '-'}
        # Find leftmost i where words[i:] is title-case-only chain
        # But also handle trailing lowercase suffix - try the longest title prefix from some start
        n = len(words)
        # For each start, find how far the title-case chain extends from i
        candidates = []
        for i in range(n):
            j = i
            while j < n:
                ww = words[j].strip("()[]'\"")
                if not ww:
                    j += 1; continue
                if ww[0].isupper() or ww in connectors or re.match(r"^[\(\)/&\-\']", ww):
                    j += 1
                else:
                    break
            if j > i and words[i][0].isupper():
                cand = ' '.join(words[i:j])
                # strip trailing connector
                cand = re.sub(r'\s+(and|of|the|a|an|on|or|for|in)$', '', cand)
                cand = cand.strip().strip("'\".,")
                if cand and len(cand) <= 60 and not re.search(r'\d', cand):
                    # prefer earlier start (leftmost) → longer
                    return cand
        return None

    cleaned = [title_tail(c) for c in chunks]

    runs = []
    cur = []
    for c in cleaned:
        if c is None:
            if len(cur) >= 1:
                runs.append(cur)
            cur = []
        else:
            cur.append(c)
    if len(cur) >= 1:
        runs.append(cur)

    cats = []
    for r in runs:
        cats.extend(r)
    # Filter known non-categories
    BAD = {'This', 'It', 'A', 'An', 'The'}
    cats = [c for c in cats if c not in BAD]
    # Remove cats that start with "This " (referring to location)
    cats = [c for c in cats if not c.startswith('This ')]
    seen = set(); out = []
    for c in cats:
        if c not in seen:
            seen.add(c); out.append(c)
    return out

